local successGui, errGui = pcall(function()
    loadstring(game:HttpGet(GUI_URL))()
end)

if not successGui then
    warn("[BloxyScripts]: Ошибка загрузки GUI -> " .. tostring(errGui))
    return
end

local successAddon, errAddon = pcall(function()
    loadstring(game:HttpGet(ADDON_URL))()
end)

